WHITE = "W"
BLACK = "B"
NONE = ""


class Board:
    """Count territories of each player in a Go game

    Args:
        board (list[str]): A two-dimensional Go board
    """

    def __init__(self, board):
        self._board = board
        self._rows = len(board)

    def territory(self, x, y):
        """Find the owner and the territories given a coordinate on
           the board

        Args:
            x (int): Column on the board
            y (int): Row on the board

        Returns:
            (str, set): A tuple, the first element being the owner
                        of that area.  One of "W", "B", "".  The
                        second being a set of coordinates, representing
                        the owner's territories.
        """
        if not self._in_bounds(x, y):
            raise ValueError("Invalid coordinate")

        if self._board[y][x] != " ":
            return NONE, set()

        region = self._region(x, y)
        return self._owner(region), region

    def territories(self):
        """Find the owners and the territories of the whole board

        Args:
            none

        Returns:
            dict(str, set): A dictionary whose key being the owner
                        , i.e. "W", "B", "".  The value being a set
                        of coordinates owned by the owner.
        """
        result = {WHITE: set(), BLACK: set(), NONE: set()}
        visited = set()
        for y in range(self._rows):
            for x in range(len(self._board[y])):
                if self._board[y][x] == " " and (x, y) not in visited:
                    region = self._region(x, y)
                    visited |= region
                    result[self._owner(region)] |= region
        return result

    def _in_bounds(self, x, y):
        return (
            0 <= y < self._rows
            and 0 <= x < len(self._board[y])
        )

    def _region(self, x, y):
        """Flood-fill the connected empty region containing (x, y)."""
        region = set()
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) in region:
                continue
            region.add((cx, cy))
            for nx, ny in ((cx + 1, cy), (cx - 1, cy), (cx, cy + 1), (cx, cy - 1)):
                if self._in_bounds(nx, ny) and self._board[ny][nx] == " ":
                    stack.append((nx, ny))
        return region

    def _owner(self, region):
        """Return the owner of a region: the single color that borders
        every stone adjacent to the region, or NONE if the region is
        bordered by both colors (or no stones at all)."""
        borders = set()
        for x, y in region:
            for nx, ny in ((x + 1, y), (x - 1, y), (x, y + 1), (x, y - 1)):
                if self._in_bounds(nx, ny):
                    stone = self._board[ny][nx]
                    if stone != " ":
                        borders.add(stone)
        if len(borders) == 1:
            return borders.pop()
        return NONE
